function validate([s, k]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 1000) return 's needs 1 to 1000 characters.';
  if (!/^[01]+$/.test(s)) return "s may contain only '0' and '1'.";
  if (!Number.isInteger(k) || k < 1 || k > 1e9) return 'k is an integer between 1 and 10^9.';
  return null;
}

