function longestSubsequence(s, k) {
  // DP left to right: smallest[len] is the least value of any chosen subsequence of that length
  // (Infinity once it exceeds k). Appending a bit maps v to 2v + bit, which keeps the order of values.
  const n = s.length;
  const smallest = new Array(n + 1).fill(Infinity);
  smallest[0] = 0;
  for (let i = 0; i < n; i++) {
    const bit = s[i] === '1' ? 1 : 0;
    for (let len = i; len >= 0; len--) {
      if (smallest[len] === Infinity) continue;
      const next = smallest[len] * 2 + bit;
      if (next <= k && next < smallest[len + 1]) smallest[len + 1] = next;
    }
  }
  let best = 0;
  for (let len = 0; len <= n; len++) if (smallest[len] <= k) best = len;
  return best;
}

