function generate(rand, size) {
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 12);
  const density = rand();
  let s = '';
  for (let i = 0; i < n; i++) s += rand() < density ? '1' : '0';
  let k;
  if (size === 'large') {
    k = rand() < 0.2 ? 1e9 : 1 + Math.floor(rand() * 1e9);
  } else {
    const roll = rand();
    k = roll < 0.15 ? 1 : 1 + Math.floor(rand() * Math.min(2 ** (n + 1), 1e9));
  }
  return [s, k];
}
